<div class="login-page"><div class="login-panel"><div class="login-brand"><div class="brand-mark large">SP</div><h2>Reset password</h2></div><div class="card border-0 shadow-lg p-4 p-md-5"><?php if($m=\App\Core\Session::consume('error')):?><div class="alert alert-danger"><?= e($m) ?></div><?php endif; ?><?php if(!$valid):?><div class="alert alert-danger">Reset link tidak valid atau sudah kedaluwarsa.</div><a class="btn btn-primary w-100" href="<?= url('/forgot-password') ?>">Request new link</a><?php else:?><form method="post" action="<?= url('/reset-password') ?>"><?= csrf_field() ?><input type="hidden" name="token" value="<?= e($token) ?>"><label class="form-label">New Password</label><input class="form-control mb-3" type="password" name="password" minlength="8" required><label class="form-label">Confirm Password</label><input class="form-control mb-4" type="password" name="password_confirmation" minlength="8" required><button class="btn btn-primary w-100">Reset Password</button></form><?php endif;?></div></div></div>
